-- Prospect audit results for the self-running Outreach Engine.
create table if not exists public.prospect_audits (
  slug text primary key,
  name text, city text, vertical text, domain text,
  rank int, count int, score int, field_avg int,
  leads boolean default false,
  top_gap text, dmarc text,
  competitors jsonb default '[]'::jsonb,
  updated_at timestamptz not null default now()
);
alter table public.prospect_audits enable row level security;
-- No anon policies: reads/writes go through the server (service-role) only.

on conflict (slug) do update set
  name=excluded.name, city=excluded.city, vertical=excluded.vertical, domain=excluded.domain,
  rank=excluded.rank, count=excluded.count, score=excluded.score, field_avg=excluded.field_avg,
  leads=excluded.leads, top_gap=excluded.top_gap, dmarc=excluded.dmarc, competitors=excluded.competitors,
  updated_at=now();
